$wait = [Diagnostics.Stopwatch]::StartNew()
$lock = Enter-P9SLock $Ctx $Ctx.EmergencyLockWaitMs
$hold = $null
if ($lock) {
    $hold = Enter-P9SEmergencyHold $Ctx ([Math]::Max(0, $Ctx.EmergencyLockWaitMs - [int]$wait.ElapsedMilliseconds))
    if ($hold) {
        $null = Add-P9SStopRequestIfAbsent $Ctx
    } else { $lock.Dispose(); $lock = $null }
}

